/**
 * What the generated operation registry must still be true of, independently of the generator that wrote it.
 *
 * The generator asserts its own census before it writes, which catches an extraction that changed. These
 * assertions catch the other direction: a registry hand-edited, half-regenerated, or regenerated by a
 * generator whose own decision tables moved. Every one of them is checkable from the committed file alone.
 */
import { describe, expect, it } from "vitest";

import { PRISMA_PROBE_CENSUS, prismaProbeEvidenceFor } from "../../../../atlas/prismaDataPlatform/apiProbe.js";
import {
  PRISMA_DEPRECATED_OPERATIONS,
  PRISMA_SPEC_CENSUS,
  PRISMA_SPEC_PIN,
  PRISMA_STABILITY_CENSUS,
  PRISMA_UNDECLARED_TAGS,
} from "../../../../atlas/prismaDataPlatform/generated/specLock.js";
import { PRISMA_DATA_PLATFORM_SURFACES } from "../../../../atlas/prismaDataPlatform/generated/surfaces.js";
import {
  PRISMA_DATA_PLATFORM_ATLAS_KINDS,
  prismaDataPlatformKindFor,
} from "../../../../atlas/prismaDataPlatform/kinds.js";

describe("the generated Prisma Data Platform registry", () => {
  it("has at least one entry in PRISMA_UNDECLARED_TAGS, so the guards below are not vacuously green", () => {
    expect(PRISMA_UNDECLARED_TAGS.length).toBeGreaterThan(0);
  });

  it("holds one row per declared operation", () => {
    expect(PRISMA_DATA_PLATFORM_SURFACES.length).toBe(PRISMA_SPEC_CENSUS.operations);
  });

  it("gives every row a distinct operation id, so the id is usable as a surface name", () => {
    expect(new Set(PRISMA_DATA_PLATFORM_SURFACES.map((row) => row.name)).size).toBe(PRISMA_SPEC_CENSUS.operationIds);
  });

  it("gives every row a distinct method-and-path, which is what the two channels match on", () => {
    const keys = PRISMA_DATA_PLATFORM_SURFACES.map((row) => `${row.method} ${row.path}`);

    expect(new Set(keys).size).toBe(keys.length);
  });

  it("splits stability exactly as the pin records", () => {
    const experimental = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.stability === "experimental");

    expect(experimental.length).toBe(PRISMA_STABILITY_CENSUS.experimentalOperations);
    expect(PRISMA_DATA_PLATFORM_SURFACES.length - experimental.length).toBe(PRISMA_STABILITY_CENSUS.stableOperations);
  });

  // The headline finding of this atlas: the documentation and the stability extension partition the surface
  // identically. A test on the committed rows is what stops that claim quietly becoming false.
  it("documents exactly the stable operations and no experimental one", () => {
    const documentedExperimental = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => row.docsUrl !== null && row.stability === "experimental",
    );
    const undocumentedStable = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => row.docsUrl === null && row.stability === "stable",
    );

    expect(documentedExperimental.length).toBe(0);
    expect(undocumentedStable.length).toBe(0);
    expect(PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.docsUrl !== null).length).toBe(
      PRISMA_STABILITY_CENSUS.documentedOperations,
    );
  });

  it("names every deprecated operation the pin names, and no others", () => {
    const deprecated = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.deprecated).map((row) => row.name);

    expect(deprecated.toSorted()).toEqual([...PRISMA_DEPRECATED_OPERATIONS].toSorted());
  });

  // All eleven deprecations are one noun being renamed rather than eleven retirements — the reading
  // `specLock.ts` records, asserted against the rows so it cannot become prose nobody checks.
  it("puts every deprecated operation under /v1/apps and files it as a service", () => {
    const deprecated = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.deprecated);

    expect(deprecated.filter((row) => !row.path.startsWith("/v1/apps"))).toEqual([]);
    expect(deprecated.filter((row) => !["custom-domain", "deployment", "service"].includes(row.kind))).toEqual([]);
  });

  it("carries the served-but-undeclared tag the pin names", () => {
    const carried = new Set(PRISMA_DATA_PLATFORM_SURFACES.map((row) => row.tag));

    expect(PRISMA_UNDECLARED_TAGS.filter((tag) => !carried.has(tag))).toEqual([]);
  });

  it("gives every row a kind the kind constant declares", () => {
    const unknown = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => !PRISMA_DATA_PLATFORM_ATLAS_KINDS.includes(row.kind));

    expect(unknown).toEqual([]);
  });

  it("agrees with the kind table it was generated through", () => {
    const disagreeing = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => prismaDataPlatformKindFor({ method: row.method, path: row.path })?.kind !== row.kind,
    );

    expect(disagreeing).toEqual([]);
  });

  it("gives a reason to every row that is not a plain entity, and none to the ones that are", () => {
    const missingReason = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => row.disposition !== "entity" && row.dispositionBecause === null,
    );
    const spuriousReason = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => row.disposition === "entity" && row.dispositionBecause !== null,
    );

    expect(missingReason).toEqual([]);
    expect(spuriousReason).toEqual([]);
  });

  it("carries an exclusion reason exactly on the excluded rows", () => {
    const mismatched = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => (row.disposition === "excluded") !== (row.exclusionReason !== null),
    );

    expect(mismatched).toEqual([]);
  });

  it("excludes every non-GET as mutating, because nothing on this platform reads by POST", () => {
    const nonGet = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.method !== "GET");

    expect(nonGet.length).toBe(PRISMA_SPEC_CENSUS.operations - PRISMA_SPEC_CENSUS.methodCounts.GET);
    expect(nonGet.filter((row) => row.exclusionReason !== "mutating")).toEqual([]);
  });

  it("shape-indexes exactly the two newline-delimited log streams", () => {
    const indexed = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.disposition === "shape-index");

    expect(indexed.map((row) => row.path).toSorted()).toEqual([
      "/v1/builds/{buildId}/logs",
      "/v1/deployments/{deploymentId}/logs",
    ]);
    expect(indexed.filter((row) => row.paging !== "log-cursor")).toEqual([]);
    expect(indexed.filter((row) => row.kind !== "event-shape")).toEqual([]);
  });

  // The backups and usage operations are the two that LOOK voluminous and are not, which is the voluminous
  // criterion cutting through a family rather than along it.
  it("keeps the backup listing and the usage aggregate as entities", () => {
    const backups = PRISMA_DATA_PLATFORM_SURFACES.find((row) => row.path === "/v1/databases/{databaseId}/backups");
    const usage = PRISMA_DATA_PLATFORM_SURFACES.find((row) => row.path === "/v1/databases/{databaseId}/usage");

    expect(backups?.disposition).toBe("entity");
    expect(backups?.paging).toBe("none");
    expect(usage?.disposition).toBe("entity");
    expect(usage?.paging).toBe("none");
  });

  it("carries the probe evidence its own table decides", () => {
    const disagreeing = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => prismaProbeEvidenceFor({ method: row.method, path: row.path }) !== row.probeEvidence,
    );

    expect(disagreeing).toEqual([]);
  });

  it("confirmed every declared GET exists and found none absent", () => {
    const gets = PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.method === "GET");

    expect(gets.length).toBe(PRISMA_PROBE_CENSUS.probedGets);
    expect(gets.filter((row) => row.probeEvidence === "absent-404")).toEqual([]);
    expect(gets.filter((row) => row.probeEvidence === "unprobed-mutating")).toEqual([]);
  });

  it("probed no mutating operation at all", () => {
    const probedMutations = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => row.method !== "GET" && row.probeEvidence !== "unprobed-mutating",
    );

    expect(probedMutations).toEqual([]);
    expect(PRISMA_DATA_PLATFORM_SURFACES.filter((row) => row.method !== "GET").length).toBe(
      PRISMA_PROBE_CENSUS.unprobedMutating,
    );
  });

  it("gives every row the platform's only two scopes, or none for the unauthenticated one", () => {
    const wrongScopes = PRISMA_DATA_PLATFORM_SURFACES.filter(
      (row) => row.scopes.length > 0 && row.scopes.join(",") !== "offline_access,workspace:admin",
    );

    expect(wrongScopes).toEqual([]);
  });

  it("pins a document whose digest and byte length are both recorded", () => {
    expect(PRISMA_SPEC_PIN.documentSha256.length).toBe(64);
    expect(PRISMA_SPEC_PIN.byteLength).toBeGreaterThan(0);
    expect(PRISMA_SPEC_PIN.documentUrl).toBe("https://api.prisma.io/v1/doc");
  });
});
